"""Share raw separator construction without changing either publication contract.

Only Python construction is refactored. Every native caller still supplies its
own pavement, boundaries, Bundle identity and material. Standalone calls retain
their whole-pavement weld/count/orientation checks; local calls retain their
surface-positivity check and require the caller's subsequent assembly checks.
No geometry is stored or reused across calls or Repeat iterations.
"""
import bpy

from .path_surface_nodes import _Nodes
from . import boundary_quad_bridge_nodes as bridge
from . import bundle_median_closure_nodes as closure
from . import curved_separator_surface_nodes as surface


def build(*, assembly=False, unequal_caps=False, free_cap=False, selective_weld=False,
          graded_tail=False, varying_boundary=False, boundary_height_steps=8,
          metric_height_steps=0,quality_refinement=False):
    options = dict(unequal_caps=unequal_caps, free_cap=free_cap, graded_tail=graded_tail,
        varying_boundary=varying_boundary, boundary_height_steps=boundary_height_steps,
        metric_height_steps=metric_height_steps,quality_refinement=quality_refinement)
    core = surface.build(assembly=True, _construction_core=True, **options)
    name = core.name.replace(' / Local assembly surface', '')
    name = name.replace(' / Shared construction core v1',
        ' / Shared local publication v1' if assembly else ' / Shared standalone publication v1')
    if selective_weld:
        name += ' / Boundary-only weld'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    tree = bpy.data.node_groups.new(name, 'GeometryNodeTree'); g = _Nodes(tree)
    for key, kind, default in (
            *((key, 'NodeSocketGeometry', None) for key in ('Pavement', 'Side A', 'Side B', 'Head', 'Tail')),
            ('Cell Size', 'NodeSocketFloat', 1.), ('Bundle ID', 'NodeSocketInt', -1),
            ('Material', 'NodeSocketMaterial', None)):
        socket = tree.interface.new_socket(name=key, in_out='INPUT', socket_type=kind)
        if default is not None: socket.default_value = default
    outputs = [('Separator', 'NodeSocketGeometry'), ('Diagnostics', 'NodeSocketGeometry'), ('Valid', 'NodeSocketBool')]
    if not assembly: outputs.insert(0, ('Geometry', 'NodeSocketGeometry'))
    for key, kind in outputs:
        tree.interface.new_socket(name=key, in_out='OUTPUT', socket_type=kind)
    inp = g.node('NodeGroupInput', 'Original separator inputs')
    out = g.node('NodeGroupOutput', 'Same separator publication contract')
    call = g.node('GeometryNodeGroup', 'Shared raw construction with independent call context')
    call.node_tree = core
    for socket in call.inputs:
        g.set(inp.outputs[socket.name], socket)
    separator = call.outputs['Separator']
    checks = [call.outputs['Valid']]
    if assembly:
        positive = bridge._mesh_good(g, separator); checks.append(positive)
        seam_diagnostics = (('assembly_checks_deferred', True, 'BOOLEAN'),)
        geometries = (('Separator', separator),)
    else:
        index = g.node('GeometryNodeInputIndex', 'Original mesh index').outputs[0]
        pos = g.node('GeometryNodeInputPosition', 'Physical position').outputs[0]
        pavement = g.store(inp.outputs['Pavement'], '_bridge_key', g.xyz(0., index), 'FLOAT_VECTOR')
        weld_separator = separator; selection = None
        if selective_weld:
            pavement, weld_separator, selection = surface._reference_weld_selection(g, pavement, separator)
        combined = bridge._join(g, pavement, weld_separator)
        welded, agreement = bridge._weld(g, combined, exact_reference=True, merge_selection=selection)
        expected = call.outputs['Expected Weld']
        reduction = g.math('SUBTRACT', bridge._size(g, combined), bridge._size(g, welded))
        key = g.named('_bridge_key', 'FLOAT_VECTOR')
        exact = g.sample(inp.outputs['Pavement'], pos, g.component(key, 'Y'), 'FLOAT_VECTOR')
        welded = bridge._position(g, welded, g.switch(g.compare(g.component(key, 'X'), 0.), pos, exact, 'VECTOR'))
        positive = bridge._mesh_good(g, welded); oriented = closure._oriented_seams(g, welded)
        checks.extend((agreement, g.compare(expected, reduction), positive, oriented))
        seam_diagnostics = (('oriented', oriented, 'BOOLEAN'), ('agreement', agreement, 'BOOLEAN'),
            ('expected_weld', expected, 'INT'), ('actual_weld', reduction, 'INT'))
        geometries = (('Geometry', welded), ('Separator', separator))
    valid = g.all(*checks)
    status = call.outputs['Diagnostics']
    for key, value, kind in (('valid', valid, 'BOOLEAN'), ('positive', positive, 'BOOLEAN'), *seam_diagnostics):
        status = g.store(status, 'st_separator_'+key, value, kind)
    for key, geometry in geometries:
        g.set(g.switch(valid, None, geometry, 'GEOMETRY'), out.inputs[key])
    g.set(valid, out.inputs['Valid']); g.set(status, out.inputs['Diagnostics'])
    tree['st_shared_separator_construction'] = 1
    return tree


def interface(tree):
    return [(s.identifier, s.name, s.in_out, s.socket_type) for s in tree.interface.items_tree
            if s.item_type == 'SOCKET']


def replace_references(roots):
    """Opt in only recognized builder variants; keep every socket identifier."""
    seen = set(); pending = list(roots)
    while pending:
        tree = pending.pop()
        if tree in seen: continue
        seen.add(tree)
        pending.extend(n.node_tree for n in tree.nodes if n.type == 'GROUP' and n.node_tree)
    rows = []
    for tree in sorted(seen, key=lambda t: t.name):
        if not tree.name.startswith(surface.NAME): continue
        suffix = tree.name[len(surface.NAME):]
        # The recognized name must be reconstructed exactly. Unknown patched
        # variants are rejected instead of silently dropping their changes.
        options = dict(assembly=False, unequal_caps=False, free_cap=False, selective_weld=False,
            graded_tail=False, varying_boundary=False, boundary_height_steps=8, metric_height_steps=0)
        for text, key in ((' / Local assembly surface', 'assembly'), (' / Unequal cap counts', 'unequal_caps'),
                (' / Free cap parity', 'free_cap'), (' / Boundary-only weld', 'selective_weld'),
                (' / Graded tail cap', 'graded_tail'), (' / Convex boundary-height blend candidate', 'varying_boundary')):
            if suffix.startswith(text): options[key] = True; suffix = suffix[len(text):]
        if options['varying_boundary']:
            for prefix, key in ((' / Pinned height fairing ', 'boundary_height_steps'),
                                (' / Metric heights ', 'metric_height_steps')):
                if suffix.startswith(prefix):
                    digits = suffix[len(prefix):].split(' / ', 1)[0]
                    if not digits.isdecimal(): raise ValueError(('Unknown iteration count', tree.name))
                    options[key] = int(digits); suffix = suffix[len(prefix)+len(digits):]
        if suffix==' / Pinned XY quality v1':options['quality_refinement']=True;suffix=''
        if suffix: raise ValueError(('Unrecognized separator construction', tree.name))
        candidate = build(**options)
        if interface(tree) != interface(candidate):
            raise ValueError(('Changed separator interface', tree.name))
        rows.append(dict(original=tree.name, candidate=candidate.name, original_nodes=len(tree.nodes),
                         wrapper_nodes=len(candidate.nodes), options=options))
        tree.user_remap(candidate)
    if not rows: raise ValueError('No known separator constructions were replaced')
    return rows
